def get_total_number_of_sequences(m, n):
    def is_valid(k):
        if k < 1:
            return False
        if k % 2 == 0:
            return False
        if k > m:
            return False
        return True
    ans = []
    for i in range(1, n + 1):
        if not is_valid(i):
            continue
        ans.append(i)
    return len(ans)

