def lps(str):
    n = len(str)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        if str[i] == '1':
            dp[i + 1][j] = max(dp[i][j], dp[i + 1][j - 1] + 1)
    return max([dp[i][j] for i in range(n) for j in range(n)])

