def max_subarray_product(arr):
    max_prod = -1
    s = 0
    for num in arr:
        if num < 0:
            s = -s
        else:
            s += num
        if s < 0:
            s = 0
        max_prod = max(s, max_prod)
    if max_prod == -1:
        max_prod = max((-i for i in arr)
    return max_prod

